// The ORIGINAL (full-colour) logos of the languages GitHub reports, by GitHub's language name — the
// brands' own colours, as devicon draws them (devicon 2.18.0, MIT — https://devicon.dev; the brands
// remain their owners' trademarks). Each entry is the whole `<svg>` of icons/<file> in the devicon
// package, drawn with react-native-svg's SvgXml. Bundled, not fetched: the logos show offline and the
// phone never asks a third party for them.
//
// A language devicon has no original logo for keeps the one-colour Simple Icons glyph
// (language-logos.ts), and one without either keeps its monogram.
//
// language-original-logos.test.ts checks every entry against the installed devicon package, so an
// entry cannot drift from its source. To add a language, map its GitHub name to the devicon file here
// and copy that file's contents — the test names any mismatch.

export interface LanguageOriginalLogo {
	/** The devicon file the logo comes from (`icons/<file>`). */
	readonly file: string;
	/** The whole SVG document. */
	readonly xml: string;
}

